// Launch Params: the launch row is the whole contract of Discover Discolike Companies (ruled
// 2026-09-09): Client (resolves the base), Query ID (the saved DiscoLike query: an Insert runs on
// a source, and the query is the source), Tag (optional, stamped on every company landed). Table is
// implied (Companies). Nothing else is read: the contacts pull it fires afterwards is Enrich
// Contacts with its own rules; no Tiers, Sources, Departments, Roles or Max companies.
//
// REFUSALS. A badly filled launch row is an expected outcome, not a crash, and it must be visible on
// the row the Operator launched: every guard RETURNS a refusal item (`refused` carries the reason),
// Launch OK? routes it to Build Refusal, which closes the row as Failed with the reason and the
// link. Nothing is pulled and nothing is written.
const rec=$('Fetch Launch Record').first().json||{};
const f=rec.fields||{};
const cf=(($('Resolve Base').first().json||{}).fields)||{};
const base=((cf['Clayroots Base ID']||'')+'').trim();
const arr=(v)=>Array.isArray(v)?v:(v==null||v===''?[]:[v]);
const clientRecId=(arr(f['Client']).map(x=>(x&&typeof x==='object')?x.id:x)[0])||'';
const queryId=((f['Query ID']||'')+'').trim();
const tag=((f['Tag']||'')+'').trim();
const startedAt=new Date().toISOString();
const where='Launch record '+(rec.id||'?');
const refuse=(reason)=>[{ json:{ refused: reason, base, clientRecId, queryId, tag, _launchRecordId: rec.id||'', startedAt } }];
if(!clientRecId){ return refuse(where+' has no Client link. Nothing was pulled.'); }
if(!/^app[A-Za-z0-9]{14}$/.test(base)){ return refuse('Client on '+where.toLowerCase()+' has no valid Clayroots Base ID. Nothing was pulled.'); }
if(!queryId){ return refuse(where+' has no Query ID. This Rootflow runs on a saved DiscoLike query; paste its id. Nothing was pulled.'); }
if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(queryId)){ return refuse('Query ID "'+queryId+'" is not a saved DiscoLike query id (uuid). Save the query in DiscoLike first. Nothing was pulled.'); }
return [{ json:{ refused:'', base, clientRecId, queryId, tag, _launchRecordId: rec.id||'', startedAt } }];

// Build Refusal: the row a badly filled launch writes. Launch Params names the reason instead of
// throwing, Launch OK? routes here, and this closes the launch row (already stamped Running with
// this Execution ID) as Failed with the reason and the link. Nothing ran.
const p=$('Launch Params').first().json||{};
const reason=String(p.refused||'the launch row was refused and no reason was recorded');
const show=(v)=>(v===''||v===null||v===undefined)?'(empty)':String(v);
const lines=[
  '**Refused before anything ran: '+reason+'**',
  '',
  '**The launch row as this Rootflow read it**',
  '- **Client:** '+show(p.clientRecId),
  '- **Clayroots Base ID:** '+(p.base||'(empty, or the Clients row could not be read)'),
  '- **Query ID:** '+show(p.queryId),
  '- **Tag:** '+show(p.tag),
  '',
  '**Failures (1)**',
  '- Launch guard: '+reason,
  '',
  'DiscoLike was not called and nothing was written to the client base.',
  'Fill the named field on the launch row, clear Execution ID and Status, and the launch automation fires it again.'
];
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const log={ 'Automation':'Discover Discolike Companies', 'Status':'Failed', 'Trigger':'form', 'Errors':1, 'Run at':$now.toISO(), 'Records In':0, 'Records Out':0, 'Duration s':dur, 'Description':lines.join('\n'), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id, 'Execution ID':String($execution.id) };
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json: log }];

// Format Companies: one DiscoLike discover profile in, one Companies row out, in the
// register's shape. Employees accepts both a band ("51-200") and a number. Rows with no domain
// are counted and dropped; duplicate domains within the pull collapse to one. Nothing here
// reads the base: the column check, the open-field rule, DNC, Clean Fields, Domain Source and
// Tag belong to the helper (Insert domains to Clayroots), which gets its contract as _meta on
// the first row. _stats rides on the first row for the log; the helper strips every "_" key.
const p=$('Launch Params').first().json;
const BANDS=['1-10','11-50','51-200','201-500','501-1000','1001-5000','5001-10000','10001+'];
const band=(v)=>{ const s=String(v==null?'':v).trim(); if(!s) return ''; if(BANDS.indexOf(s)>-1) return s; const n=Number(s.replace(/[,\s]/g,'')); if(!isFinite(n)||n<=0) return ''; if(n<=10) return '1-10'; if(n<=50) return '11-50'; if(n<=200) return '51-200'; if(n<=500) return '201-500'; if(n<=1000) return '501-1000'; if(n<=5000) return '1001-5000'; if(n<=10000) return '5001-10000'; return '10001+'; };
const join=(a)=>Array.isArray(a)?a.filter(Boolean).map(String).join(', '):(a==null?'':String(a));
const kv=(o)=>o&&typeof o==='object'&&!Array.isArray(o)?Object.entries(o).map(([k,v])=>k+':'+(typeof v==='number'?v.toFixed(2):v)).join(', '):join(o);
const keys=(o)=>o&&typeof o==='object'&&!Array.isArray(o)?Object.keys(o).join(', '):join(o);
const norm=(d)=>String(d||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
// DiscoLike Discover continues on error (ruled 2026-09-09: a dead API or a missing credential is a
// logged skip, never a crash): an error item is counted here and the log names it.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const seen=new Set(); const out=[]; const stats={ pulled:0, no_domain:0, duplicate:0, providerErrors:0, providerReason:'' };
for(const it of $input.all()){
  const c=it.json||{}; if(!Object.keys(c).length) continue;
  if(c.error&&c.domain===undefined){ stats.providerErrors++; if(!stats.providerReason) stats.providerReason=errMsg(c.error).slice(0,160); continue; }
  stats.pulled++;
  const d=norm(c.domain); if(!d){ stats.no_domain++; continue; }
  if(seen.has(d)){ stats.duplicate++; continue; } seen.add(d);
  const addr=c.address||{};
  out.push({ json: {
    'Domain': d,
    'Company': String(c.name||'').trim(),
    'Description': String(c.description||''),
    'Industry Groups': kv(c.industry_groups),
    'Business Model': kv(c.business_model),
    'Employees': band(c.employees),
    'Revenue Range': String(c.revenue_range||''),
    'Keywords': keys(c.keywords),
    'Country': String(addr.country||''), 'State': String(addr.state||''), 'City': String(addr.city||''),
    'Street': String(addr.street||''), 'Zip': String(addr.zip||''),
    'Phones': join(c.phones), 'Public Emails': join(c.public_emails), 'public_emails_clean': '',
    'Social URLs': join(c.social_urls),
    'MX Provider': String(c.mx_provider||''), 'Redirect Domain': String(c.redirect_domain||'')
  } });
}
if(!out.length) return [{ json: { _empty:true, _stats:stats } }];
out[0].json._stats=stats;
out[0].json._meta={ base:p.base, clientRecId:p.clientRecId, tag:p.tag||'', domainSource:'DiscoLike', allowNew:true };
return out;

// Fire Contacts: one item in Enrich Contacts' event shape (its Event Row reads launch-row keys),
// so the companies just landed get their people at once. Client, Table Companies, View Not Sourced,
// Tag, and Domains = exactly the domains this run landed, so on a base with a backlog the contacts
// pull is scoped to this pull and never re-sweeps the whole view (ruled 2026-09-09). Enrich
// Contacts writes its own launch row; nothing else is passed.
const p=$('Launch Params').first().json;
let domains=[];
try{ domains=$('Format Companies').all().map(i=>String((i.json||{}).Domain||'').trim().toLowerCase()).filter(Boolean); }catch(e){}
return [{ json:{ Client:[p.clientRecId], Table:'Companies', View:'Not Sourced', Tag:p.tag||'', Domains:Array.from(new Set(domains)) } }];

// Build Log: one row per run, on the launch row, status computed from the helper's failed[] and the
// provider verdict, skips separated from errors, Client attached. The funnel is the pull's own
// counts plus the helper's counters (Insert domains to Clayroots). A DiscoLike that could not be
// reached (no credential, dead API) is a logged skip, never a crash: the row closes as Failed only
// when nothing could be pulled for that reason.
const p=$('Launch Params').first().json;
let stats={ pulled:0, no_domain:0, duplicate:0, providerErrors:0, providerReason:'' };
try{ const f=$('Format Companies').first().json||{}; if(f._stats) stats=Object.assign(stats, f._stats); }catch(e){}
let h=null; try{ h=$('Insert Domains').first().json||null; }catch(e){}
let fired=false, scope=0; try{ const fc=$('Fire Contacts').first().json||{}; fired=true; scope=(fc.Domains||[]).length; }catch(e){}
const n=(v)=>Number(v)||0;
const failed=(h&&Array.isArray(h.failed))?h.failed.slice():[];
const providerDown=!stats.pulled&&stats.providerErrors>0;
if(providerDown) failed.push({ name:'DiscoLike', reason:'DiscoLike could not be pulled: '+stats.providerReason });
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const tableName=(h&&h.tableName)||'Companies';
const lines=[
  '**'+stats.pulled+' companies pulled, '+n(h&&h.upserted)+' landed on '+tableName+' ('+n(h&&h.newDomains)+' new, '+n(h&&h.existingDomains)+' already held and refreshed)**',
  '',
  '**Source:** DiscoLike saved query '+p.queryId,
  '**Tag:** '+(p.tag||'none'),
  '**Rule:** every company the query answers is landed on Domain; a held company is refreshed with the new pull (Domain Source kept, Tag re-stamped); custom columns in the pull land as columns; DNC domains dropped',
  '',
  '**Funnel**',
  '- **Pulled:** '+stats.pulled,
  '- **Handed to the helper:** '+n(h&&h.in),
  '- **Landed (record id returned):** '+n(h&&h.upserted)+' ('+n(h&&h.newDomains)+' new, '+n(h&&h.existingDomains)+' already held)',
  '- **With public emails:** '+n(h&&h.withEmails)
];
if(h&&Array.isArray(h.createdColumns)&&h.createdColumns.length) lines.push('- **Columns created:** '+h.createdColumns.join(', '));
if(h&&Array.isArray(h.droppedKeys)&&h.droppedKeys.length) lines.push('- **Keys dropped:** '+h.droppedKeys.map(d=>d.key+' ('+d.why+')').join(', '));
lines.push('', '**Contacts:** '+(fired?('Enrich Contacts fired once on Companies view "Not Sourced", scoped to the '+scope+' domains of this pull; it writes its own launch row'):'not fired, nothing landed'));
const skips=[];
if(stats.no_domain) skips.push(stats.no_domain+' no domain');
if(stats.duplicate) skips.push(stats.duplicate+' duplicate domain in the pull');
if(h&&n(h.dnc)) skips.push(n(h.dnc)+' on the DNC table');
if(stats.providerErrors&&stats.pulled) skips.push(stats.providerErrors+' DiscoLike page(s) failed ('+stats.providerReason+')');
if(skips.length) lines.push('', '**Skipped ('+skips.join(', ')+')**');
if(failed.length){ const byReason={}; for(const f of failed){ byReason[f.reason]=(byReason[f.reason]||0)+1; } lines.push('', '**Failures ('+failed.length+')**'); for(const [r,c] of Object.entries(byReason).slice(0,10)) lines.push('- '+c+' x '+r); }
const log={
  'Automation':'Discover Discolike Companies',
  'Status': providerDown?'Failed':(failed.length?'Succeeded with errors':'Succeeded'),
  'Trigger':'form',
  'Errors': failed.length,
  'Run at': $now.toISO(),
  'Target': tableName+' ('+((h&&h.tableId)||'')+')',
  'Records In': stats.pulled,
  'Records Out': n(h&&h.upserted),
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Execution ID': String($execution.id),
  'Client': [p.clientRecId]
};
return [{ json: log }];
